// Bo sung vao lop Account.cs
public void Withdraw(decimal withdrawalAmount)
{
   if (withdrawalAmount > 0.0m)
   {
      if (withdrawalAmount <= Balance)
      {
         Balance = Balance - withdrawalAmount; // Tru tien hop le
      }
      else
      {
         Console.WriteLine("Withdrawal amount exceeded account balance.");
      }
   }
}
```

Mã nguồn lớp Student.cs chuẩn mực:

```csharp
public class Student
{
   public string Id { get; set; }
   public string Name { get; set; }
   private decimal score1;
   private decimal score2;
   private decimal score3;

   public Student(string id, string name, decimal s1, decimal s2, decimal s3)
   {
      Id = id;
      Name = name;
      Score1 = s1;
      Score2 = s2;
      Score3 = s3;
   }

   public decimal Score1
   {
      get { return score1; }
      set { if (value >= 0.0m) score1 = value; }
   }

   public decimal Score2
   {
      get { return score2; }
      set { if (value >= 0.0m) score2 = value; }
   }

   public decimal Score3
   {
      get { return score3; }
      set { if (value >= 0.0m) score3 = value; }
   }

   public decimal GetAggregate() => Score1 + Score2 + Score3;
   public decimal GetPercentage() => (GetAggregate() / 50.0m) * 100.0m;
}
```

Mã nguồn lớp Asset.cs chuẩn mực:

```csharp
public class Asset
{
   public string AssetName { get; set; }
   private decimal assetValue;
   private decimal depreciationRate;

   public Asset(string name, decimal val, decimal rate)
   {
      AssetName = name;
      AssetValue = val;
      DepreciationRate = rate;
   }

   public decimal AssetValue
   {
      get => assetValue;
      set { if (value >= 0.0m) assetValue = value; }
   }

   public decimal DepreciationRate
   {
      get => depreciationRate;
      set { if (value >= 0.0m && value <= 1.0m) depreciationRate = value; }
   }

   public decimal GetDepreciationAmount() => AssetValue * DepreciationRate;
   public decimal GetDepreciatedValue() => AssetValue - GetDepreciationAmount();
}
```

