Mã nguồn lớp HeartRates.cs y tế số:

```csharp
public class HeartRates
{
   public string FirstName { get; set; }
   public string LastName { get; set; }
   public int BirthYear { get; set; }
   public int CurrentYear { get; set; }

   public HeartRates(string firstName, string lastName, int birthYear, int currentYear)
   {
      FirstName = firstName;
      LastName = lastName;
      BirthYear = birthYear;
      CurrentYear = currentYear;
   }

   public int Age => CurrentYear - BirthYear;
   public int MaxHeartRate => 220 - Age;
   public double MinTargetRate => MaxHeartRate * 0.50;
   public double MaxTargetRate => MaxHeartRate * 0.85;
}
```

Mã nguồn lớp HealthProfile.cs chuẩn y tế quốc tế:

```csharp
public class HealthProfile
{
   public string Name { get; set; }
   public string Gender { get; set; }
   public int BirthYear { get; set; }
   public int CurrentYear { get; set; }
   public double HeightCm { get; set; }
   public double WeightKg { get; set; }

   public HealthProfile(string name, string gender, int birthYear, int currentYear, double height, double weight)
   {
      Name = name;
      Gender = gender;
      BirthYear = birthYear;
      CurrentYear = currentYear;
      HeightCm = height;
      WeightKg = weight;
   }

   public int Age => CurrentYear - BirthYear;
   public int MaxHeartRate => 220 - Age;
   public double BMI
   {
      get
      {
         double heightM = HeightCm / 100.0;
         return WeightKg / (heightM * heightM);
      }
   }
}
```
